// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);

        c.seedMarket{value: 1 ether}(1);

        address A = address(0x1);
        vm.deal(A, 1 ether);
        vm.prank(A);
        c.getFreeKilo();

        vm.warp(block.timestamp + 86400);

        vm.prank(A);
        c.collectDrugs(A);

        uint256 drugsUsed = 86400 * 300;
        uint256 expectedRef = drugsUsed / 5;
        assertTrue(c.claimedDrugs(A) == expectedRef, "Reference should have claimedDrugs[A] = drugsUsed/5, mutant clears it");
    }
}
